#folderPane {
  grid-area: folders;
  box-sizing: border-box;
  /* Matches the collapse-width on the splitter. */
  min-inline-size: 100px;
  overflow: hidden;
  background-color: var(--sidebar-background);
  color: var(--sidebar-color);
  user-select: none;
  display: flex;
  flex-direction: column;
  contain: strict;
}
